package primitives

import (
	"bytes"
	"errors"
	"fmt"
	"go/format"
	"go/parser"
	"io/fs"
	"maps"
	"path"
	"slices"
	"strconv"
	"strings"

	"golang.org/x/mod/modfile"
)

// ImportsTestFile is the generated test each package under an imports
// rule carries.
const ImportsTestFile = "primitives_imports_test.go"

// Generate renders every generated file, keyed by repo-relative path.
func (c *Registry) Generate() (map[string][]byte, error) {
	module, err := modulePath(c.fsys)
	if err != nil {
		return nil, err
	}
	type ban struct{ deny, primitive, why, instead string }
	type packageBans struct {
		name string
		bans []ban
	}
	byPkg := map[string]packageBans{}
	for _, p := range c.Primitives {
		for _, rule := range p.Imports {
			deny, _, err := resolveGoPackage(c.fsys, rule.Deny)
			if err != nil {
				return nil, fmt.Errorf("primitive %s: deny %w", p.ID, err)
			}
			entry := ban{path.Join(module, deny), p.ID, rule.Why, rule.Instead}
			for _, from := range rule.From {
				dir, name, err := resolveGoPackage(c.fsys, from.Value)
				if err != nil {
					return nil, fmt.Errorf("primitive %s: from %w", p.ID, err)
				}
				group := byPkg[dir]
				group.name = name
				group.bans = append(group.bans, entry)
				byPkg[dir] = group
			}
		}
	}
	out := map[string][]byte{}
	for _, dir := range slices.Sorted(maps.Keys(byPkg)) {
		pkg := byPkg[dir]
		bans := pkg.bans
		slices.SortFunc(bans, func(a, b ban) int { return strings.Compare(a.deny+a.primitive, b.deny+b.primitive) })
		var b bytes.Buffer
		fmt.Fprintf(&b, "// Code generated by cmd/primitives from %s/; DO NOT EDIT.\n\npackage %s_test\n\n", Dir, pkg.name)
		fmt.Fprintf(&b, "import (\n\t\"testing\"\n\n\t%s\n)\n\n", strconv.Quote(path.Join(module, "internal/importcheck")))
		b.WriteString("func TestPrimitiveImports(t *testing.T) {\n\timportcheck.Run(t,\n")
		for _, x := range bans {
			fmt.Fprintf(&b, "\t\timportcheck.Ban{Deny: %s, Primitive: %s, Why: %s, Instead: %s},\n", strconv.Quote(x.deny), strconv.Quote(x.primitive), strconv.Quote(x.why), strconv.Quote(x.instead))
		}
		b.WriteString("\t)\n}\n")
		src, err := format.Source(b.Bytes())
		if err != nil {
			return nil, fmt.Errorf("format %s: %w", dir, err)
		}
		out[path.Join(dir, ImportsTestFile)] = src
	}
	return out, nil
}

// Stale compares the generated files with the tree: a path maps to
// "missing", "outdated", or "orphaned" (on disk, no longer generated).
func (c *Registry) Stale() (map[string]string, error) {
	want, err := c.Generate()
	if err != nil {
		return nil, err
	}
	stale := map[string]string{}
	for _, rel := range slices.Sorted(maps.Keys(want)) {
		got, err := fs.ReadFile(c.fsys, rel)
		switch {
		case errors.Is(err, fs.ErrNotExist):
			stale[rel] = "missing"
		case err != nil:
			return nil, err
		case !bytes.Equal(got, want[rel]):
			stale[rel] = "outdated"
		}
	}
	err = fs.WalkDir(c.fsys, ".", func(rel string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			// Where the go command would not look for a package, a
			// generated test cannot be an orphan. Those directories
			// (.git, .gofastr, _scratch) also hold what other tools
			// and tests rewrite as they run, so reading them would
			// make this check's result depend on run state.
			name := d.Name()
			if rel != "." && (strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_")) {
				return fs.SkipDir
			}
			switch name {
			case "node_modules", "dist", "testdata":
				return fs.SkipDir
			}
			return nil
		}
		if d.Name() != ImportsTestFile {
			return nil
		}
		if _, ok := want[rel]; !ok {
			stale[rel] = "orphaned"
		}
		return nil
	})
	return stale, err
}

func modulePath(fsys fs.FS) (string, error) {
	src, err := fs.ReadFile(fsys, "go.mod")
	if err != nil {
		return "", err
	}
	if mod := modfile.ModulePath(src); mod != "" {
		return mod, nil
	}
	return "", fmt.Errorf("go.mod names no module")
}

func resolveGoPackage(fsys fs.FS, entry string) (dir, name string, err error) {
	if strings.ContainsAny(entry, "*?[]") {
		return "", "", fmt.Errorf("%q must name a literal Go package directory (wildcards are unsupported)", entry)
	}
	dir = path.Clean(entry)
	files, err := fs.ReadDir(fsys, dir)
	if err != nil {
		return "", "", fmt.Errorf("%q is not a Go package directory: %w", entry, err)
	}
	for _, f := range files {
		base := f.Name()
		if f.IsDir() || !strings.HasSuffix(base, ".go") || strings.HasSuffix(base, "_test.go") ||
			strings.HasPrefix(base, ".") || strings.HasPrefix(base, "_") {
			continue
		}
		parsed, err := parseGoFile(fsys, path.Join(dir, base), parser.PackageClauseOnly)
		if err != nil {
			return "", "", fmt.Errorf("%q has unreadable or invalid Go source: %w", entry, err)
		}
		return dir, parsed.Name.Name, nil
	}
	return "", "", fmt.Errorf("%q must contain non-test Go source", entry)
}
